INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'FM-1', 'failure-modes-2026', 'Reject and retry root-cause diagnoses that contain raw tool-call markup (<|tool_call...) or no answer: 7 issues store leaked tool-call tokens as the diagnosis (6 open) and 3 root-cause issues have shown ''no answer yet'' since 2026-10-26', 'script', 'qnfo-fleet-control/worker.js', 'planned', 'agent_issues description LIKE ''%<|tool_call%'' = 7 (6 open); LIKE ''%no answer yet; the managers ask again%'' = 3 on 2026-10-28. Verify live: both counts reach 0 for new diagnoses over 7 days' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'FM-1' AND source = 'failure-modes-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'FM-2', 'failure-modes-2026', 'Diagnosis code-tasks must pass an anchor check before they are stored: cf_agent_requests #273 proposed a worker.js edit for a gate that is a D1 trigger (remediation_verification_autoclose_ins), so the code-task was unactionable', 'script', 'qnfo-fleet-control/worker.js', 'planned', 'grep of qnfo-fleet-control/worker.js finds no ''verified-remediation-trigger'' or ''VACUOUS-PROBE-V3-1''; the closer is a trigger in qnfo-audit. Verify: every stored code-task anchor resolves in the named file' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'FM-2' AND source = 'failure-modes-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'FM-3', 'failure-modes-2026', 'Close-on-single-pass with no dwell for real probes: PORTFOLIO-GAP umbrella (136 reopens), METRIC-REGRESSION-1 (209), METRIC-TRIGGER-5182 (36) close via auto:verified-remediation-trigger and reopen. Add a stability dwell (continuous passes over N hours) to the trigger for issues with reopened_count >= 2, measure first with a shadow count', 'doc', 'migrations/2026-10-28-vacuous-flap-1.sql', 'planned', 'issue_triage reopened_count >= 5 grouped by family and close_channel, 2026-10-28; PORTFOLIO-GAP and METRIC-REGRESSION-1 carry real (non-vacuous) probes, so VACUOUS-FLAP-1 does not cover them' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'FM-3' AND source = 'failure-modes-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'FM-4', 'failure-modes-2026', 'Vacuous contracts: 190 issues closed on a probe that measures nothing (50 reopened). Replace the vacuous probe with a measuring probe at issue-open time, starting with the METRIC-UNMEASURED-1 and CF-OBS-ISSUE-1 families, and report the vacuous share as a guard metric', 'script', 'qnfo-fleet-control/worker.js', 'planned', 'remediation_contracts action LIKE ''VACUOUS-PROBE%'' joined to agent_issues, 2026-10-28; VACUOUS-FLAP-1 stops the worst flaps but does not give those issues a real probe' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'FM-4' AND source = 'failure-modes-2026');
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence) SELECT 'FM-5', 'failure-modes-2026', 'Verification volume: 191,906 remediation_verifications rows in 7 days (78.6% pass), #1000473 verified every ~80 minutes with observed=0. Cap cadence for issues whose last N verifications are identical to reduce D1 rows and cost', 'script', 'qnfo-fleet-control/worker.js', 'planned', 'count and pass share from remediation_verifications, 2026-10-28; guard: verification_runtime share (#2684) must not fall' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation WHERE item = 'FM-5' AND source = 'failure-modes-2026');
